import {validateItems,totals} from './domain.js';
const owner={id:'preview-owner',display_name:'เจ้าของทดลอง'},office={id:'preview-office',display_name:'พนักงานทดลอง'};
const fields=(name,price,extra={})=>({...validateItems([{department:'ออฟฟิศ',name,spec:'ตัวอย่างสำหรับสาธิตขั้นตอน',source:'ร้านค้าตัวอย่าง',note:'ข้อมูลสังเคราะห์',qty:'2',unit:'ชิ้น',unit_price:String(price),vat:true,payment_method:'credit',...extra}])[0]});
const item=(id,name,state,price,extra={})=>{const line=fields(name,price,extra),result={...line,id,state,revision:1};if(['approved','received','revision_requested','editing'].includes(state))result.approved_snapshot={...line};if(state==='revision_requested'||state==='editing'){result.paused_from='approved';result.revision_reason='เปลี่ยนจำนวนตามใบเสนอราคาใหม่';}if(state==='returned')result.return_reason='ระบุรุ่นสินค้าให้ชัดเจน';if(state==='rejected')result.reject_reason='ไม่อยู่ในแผนจัดซื้อ';return result;};
const po=(id,number,day,items)=>({id,po_number:number,po_date:`2026-10-${String(day).padStart(2,'0')}`,created_at:`2026-10-${String(day).padStart(2,'0')}T02:00:00.000Z`,created_by:office.id,requester_name:office.display_name,version:1,closed_at:null,items,events:[{id:`${id}-create`,action:'create',actor_id:office.id,actor_name:office.display_name,item_id:null,item_name:null,at:`2026-10-${String(day).padStart(2,'0')}T02:00:00.000Z`,reason:''}]});
export function createPreviewFixtures(){const rows=[
 po('preview-v2-pending','DEMO-2026-20101',1,[item('item-pending-a','กระดาษ A4 · รออนุมัติ','pending',214),item('item-pending-b','หมึกพิมพ์ · รออนุมัติ','pending',1605)]),
 po('preview-v2-returned','DEMO-2026-20102',2,[item('item-returned','เก้าอี้สำนักงาน · ส่งกลับ','returned',2450)]),
 po('preview-v2-rejected','DEMO-2026-20103',3,[item('item-rejected','ชั้นวางเอกสาร · ไม่อนุมัติ','rejected',3800)]),
 po('preview-v2-approved','DEMO-2026-20104',4,[item('item-approved','กระดาษใบเสร็จ · อนุมัติ','approved',890)]),
 po('preview-v2-received','DEMO-2026-20105',5,[item('item-received','ถุงบรรจุอาหาร · รับแล้ว','received',1850,{payment_method:'cash'})]),
 po('preview-v2-closed','DEMO-2026-20106',6,[item('item-closed','กล่องเอกสาร · ปิด PO','received',420,{vat:false})]),
 po('preview-v2-mixed','DEMO-2026-20107',7,[item('item-mixed-approved','ถุงมือ · อนุมัติ','approved',320),item('item-mixed-received','น้ำยาทำความสะอาด · รับแล้ว','received',690,{vat:false}),item('item-mixed-pending','แก้วกระดาษ · รออนุมัติ','pending',145),item('item-mixed-returned','ป้ายสติกเกอร์ · ส่งกลับ','returned',95),item('item-mixed-rejected','แฟ้ม · ไม่อนุมัติ','rejected',210)]),
 po('preview-v2-all-rejected','DEMO-2026-20108',8,[item('item-rej-one','ปากกา · ไม่อนุมัติ','rejected',35),item('item-rej-two','ดินสอ · ไม่อนุมัติ','rejected',22,{vat:false})]),
 po('preview-v2-revision','DEMO-2026-20109',9,[item('item-revision','ข้าวสาร · ขอแก้ไข','revision_requested',1200),item('item-editing','ถุงขยะ · ปลดล็อกแล้ว','editing',590)]),
 po('preview-v2-approved-mixed','DEMO-2026-20110',10,[item('item-approved-mixed','ช้อนส้อม · อนุมัติแล้ว','approved',275),item('item-pending-mixed','ถุงมือ · ยังรออนุมัติ','pending',140)]),
 po('preview-v2-creator','DEMO-2026-20111',11,[item('item-creator','น้ำยาล้างจาน · ใบเสนอราคา','approved',1650)]),
 po('preview-v2-creator-two','DEMO-2026-20112',12,[item('item-creator-two','ถุงกระดาษ · รายการทดลอง','pending',180)])
 ];rows[5].closed_at='2026-10-06T09:00:00.000Z';for(const record of rows){record.items.forEach((row,index)=>{if(row.state==='approved')record.events.push({id:`${record.id}-approve-${index}`,action:'approve',actor_id:owner.id,actor_name:owner.display_name,item_id:row.id,item_name:row.name,at:`${record.po_date}T04:00:00.000Z`,reason:''});if(row.state==='received')record.events.push({id:`${record.id}-receive-${index}`,action:'receive',actor_id:office.id,actor_name:office.display_name,item_id:row.id,item_name:row.name,at:`${record.po_date}T06:00:00.000Z`,reason:''});if(row.state==='returned')record.events.push({id:`${record.id}-return-${index}`,action:'return',actor_id:owner.id,actor_name:owner.display_name,item_id:row.id,item_name:row.name,at:`${record.po_date}T04:00:00.000Z`,reason:row.return_reason});if(row.state==='rejected')record.events.push({id:`${record.id}-reject-${index}`,action:'reject',actor_id:owner.id,actor_name:owner.display_name,item_id:row.id,item_name:row.name,at:`${record.po_date}T04:00:00.000Z`,reason:row.reject_reason});if(row.state==='revision_requested')record.events.push({id:`${record.id}-revision-request-${index}`,action:'request_revision',actor_id:office.id,actor_name:office.display_name,item_id:row.id,item_name:row.name,at:`${record.po_date}T03:00:00.000Z`,reason:row.revision_reason});if(row.state==='editing')record.events.push({id:`${record.id}-unlock-${index}`,action:'unlock',actor_id:owner.id,actor_name:owner.display_name,item_id:row.id,item_name:row.name,at:`${record.po_date}T05:00:00.000Z`,reason:row.revision_reason});});if(record.closed_at)record.events.push({id:`${record.id}-close`,action:'close',actor_id:owner.id,actor_name:owner.display_name,item_id:null,item_name:null,at:record.closed_at,reason:''});const t=totals(record.items);record.total_cents=t.total_cents;}
 return rows;}
